create or replace function public.create_price_book_item_atomic(p_code text,p_category text,p_name text,p_description text,p_material_cost numeric,p_labor_hours numeric,p_overhead numeric,p_target_gp numeric) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$declare a public.users%rowtype; rid uuid; begin select * into a from public.users where auth_user_id=auth.uid() and active=true limit 1; if a.id is null or a.role not in ('owner','manager') or not private.has_permission('manage_pricebook') then raise exception 'Permission denied'; end if; if btrim(coalesce(p_code,''))='' or btrim(coalesce(p_category,''))='' or btrim(coalesce(p_name,''))='' then raise exception 'Code, category and name are required'; end if; if p_material_cost<0 or p_labor_hours<0 or p_overhead<0 or p_target_gp<0 or p_target_gp>=100 then raise exception 'Invalid price book values'; end if; insert into public.price_book_items(code,category,name,description,material_cost,labor_hours,overhead,target_gp,active) values(btrim(p_code),btrim(p_category),btrim(p_name),nullif(btrim(coalesce(p_description,'')),''),p_material_cost,p_labor_hours,p_overhead,p_target_gp,true) returning id into rid; insert into public.audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(a.id,'create_price_book_item','price_book_item',rid::text,jsonb_build_object('code',p_code,'category',p_category,'name',p_name,'material_cost',p_material_cost,'labor_hours',p_labor_hours,'overhead',p_overhead,'target_gp',p_target_gp)); return rid; end$$;
create or replace function public.update_price_book_item_atomic(p_id uuid,p_material_cost numeric,p_labor_hours numeric,p_overhead numeric,p_target_gp numeric) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$declare a public.users%rowtype; old public.price_book_items%rowtype; begin select * into a from public.users where auth_user_id=auth.uid() and active=true limit 1; if a.id is null or a.role not in ('owner','manager') or not private.has_permission('manage_pricebook') then raise exception 'Permission denied'; end if; if p_material_cost<0 or p_labor_hours<0 or p_overhead<0 or p_target_gp<0 or p_target_gp>=100 then raise exception 'Invalid price book values'; end if; select * into old from public.price_book_items where id=p_id for update; if not found then raise exception 'Price book item not found'; end if; update public.price_book_items set material_cost=p_material_cost,labor_hours=p_labor_hours,overhead=p_overhead,target_gp=p_target_gp,updated_at=now() where id=p_id; insert into public.audit_log(actor_user_id,action,entity_type,entity_id,before_data,after_data) values(a.id,'update_price_book_item','price_book_item',p_id::text,to_jsonb(old),jsonb_build_object('material_cost',p_material_cost,'labor_hours',p_labor_hours,'overhead',p_overhead,'target_gp',p_target_gp)); return p_id; end$$;
create or replace function public.save_price_book_tier_atomic(p_item_id uuid,p_tier text,p_name text,p_description text,p_material_cost numeric,p_labor_hours numeric,p_overhead numeric,p_target_gp numeric) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$declare a public.users%rowtype; rid uuid; old jsonb; begin select * into a from public.users where auth_user_id=auth.uid() and active=true limit 1; if a.id is null or a.role not in ('owner','manager') or not private.has_permission('manage_pricebook') then raise exception 'Permission denied'; end if; if p_tier not in ('Good','Better','Best') or btrim(coalesce(p_name,''))='' then raise exception 'Invalid tier'; end if; if p_material_cost<0 or p_labor_hours<0 or p_overhead<0 or p_target_gp<0 or p_target_gp>=100 then raise exception 'Invalid tier values'; end if; if not exists(select 1 from public.price_book_items where id=p_item_id) then raise exception 'Price book item not found'; end if; select to_jsonb(t) into old from public.price_book_tiers t where price_book_item_id=p_item_id and tier=p_tier for update; insert into public.price_book_tiers(price_book_item_id,tier,name,description,material_cost,labor_hours,overhead,target_gp,active,updated_at) values(p_item_id,p_tier,btrim(p_name),nullif(btrim(coalesce(p_description,'')),''),p_material_cost,p_labor_hours,p_overhead,p_target_gp,true,now()) on conflict(price_book_item_id,tier) do update set name=excluded.name,description=excluded.description,material_cost=excluded.material_cost,labor_hours=excluded.labor_hours,overhead=excluded.overhead,target_gp=excluded.target_gp,active=true,updated_at=now() returning id into rid; insert into public.audit_log(actor_user_id,action,entity_type,entity_id,before_data,after_data) values(a.id,'save_price_book_tier','price_book_tier',rid::text,old,jsonb_build_object('item_id',p_item_id,'tier',p_tier,'name',p_name,'material_cost',p_material_cost,'labor_hours',p_labor_hours,'overhead',p_overhead,'target_gp',p_target_gp)); return rid; end$$;
create or replace function public.create_price_book_learning_proposal_atomic(p_item_id uuid,p_tier_id uuid,p_service_type text,p_sample_size integer,p_current_hours numeric,p_proposed_hours numeric,p_current_gp numeric,p_proposed_gp numeric,p_evidence text) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$declare a public.users%rowtype; rid uuid; begin select * into a from public.users where auth_user_id=auth.uid() and active=true limit 1; if a.id is null or a.role not in ('owner','manager') or not private.has_permission('manage_pricebook') then raise exception 'Permission denied'; end if; if p_sample_size<1 or p_proposed_hours<0 or p_proposed_gp<0 or p_proposed_gp>=100 then raise exception 'Invalid proposal'; end if; if not exists(select 1 from public.price_book_items where id=p_item_id) then raise exception 'Price book item not found'; end if; if p_tier_id is not null and not exists(select 1 from public.price_book_tiers where id=p_tier_id and price_book_item_id=p_item_id) then raise exception 'Invalid price-book tier'; end if; insert into public.price_book_learning_proposals(price_book_item_id,price_book_tier_id,service_type,sample_size,current_labor_hours,proposed_labor_hours,current_target_gp,proposed_target_gp,evidence) values(p_item_id,p_tier_id,nullif(btrim(coalesce(p_service_type,'')),''),p_sample_size,p_current_hours,p_proposed_hours,p_current_gp,p_proposed_gp,jsonb_build_object('summary',coalesce(p_evidence,''))) returning id into rid; insert into public.audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(a.id,'create_price_book_learning_proposal','price_book_learning_proposal',rid::text,jsonb_build_object('item_id',p_item_id,'tier_id',p_tier_id,'sample_size',p_sample_size,'proposed_labor_hours',p_proposed_hours,'proposed_target_gp',p_proposed_gp)); return rid; end$$;
create or replace function public.update_company_pricing_settings_atomic(p_labor_rate numeric,p_minimum_gp numeric,p_default_overhead numeric,p_membership_discount numeric,p_allow_owner_below_floor boolean) returns boolean language plpgsql security definer set search_path=public,private,pg_temp as $$declare a public.users%rowtype; begin select * into a from public.users where auth_user_id=auth.uid() and active=true limit 1; if a.id is null or a.role not in ('owner','manager') or not private.has_permission('manage_pricing_settings') then raise exception 'Permission denied'; end if; if p_labor_rate<=0 or p_minimum_gp<0 or p_minimum_gp>=100 or p_default_overhead<0 or p_membership_discount<0 or p_membership_discount>=100 then raise exception 'Invalid pricing settings'; end if; update public.company_pricing_settings set labor_rate=p_labor_rate,minimum_gp=p_minimum_gp,default_overhead=p_default_overhead,membership_discount_pct=p_membership_discount,allow_owner_below_floor=p_allow_owner_below_floor,updated_at=now(),updated_by=a.id where id=true; if not found then raise exception 'Pricing settings unavailable'; end if; return true; end$$;
revoke all on function public.create_price_book_item_atomic(text,text,text,text,numeric,numeric,numeric,numeric),public.update_price_book_item_atomic(uuid,numeric,numeric,numeric,numeric),public.save_price_book_tier_atomic(uuid,text,text,text,numeric,numeric,numeric,numeric),public.create_price_book_learning_proposal_atomic(uuid,uuid,text,integer,numeric,numeric,numeric,numeric,text),public.update_company_pricing_settings_atomic(numeric,numeric,numeric,numeric,boolean) from public;
grant execute on function public.create_price_book_item_atomic(text,text,text,text,numeric,numeric,numeric,numeric),public.update_price_book_item_atomic(uuid,numeric,numeric,numeric,numeric),public.save_price_book_tier_atomic(uuid,text,text,text,numeric,numeric,numeric,numeric),public.create_price_book_learning_proposal_atomic(uuid,uuid,text,integer,numeric,numeric,numeric,numeric,text),public.update_company_pricing_settings_atomic(numeric,numeric,numeric,numeric,boolean) to authenticated;